(* [comment removed for export] *)
Lemma xclient_range_static : forall LB SP X A n,
  0x7e000 <= A -> A + n <= 0xb8000 ->
  (A + n <= RLIBC \/ RCTX + 928 <= A) -> (A + n <= RERRNO \/ RERRNO + 4 <= A) ->
  (A + n <= RSSP_GUARD \/ RSSP_GUARD + 8 <= A) -> (A + n <= RGOT_SSP \/ RGOT_SSP + 8 <= A) -> (A + n <= RVMLOCK \/ RVMLOCK + 4 <= A) ->
  Forall (fun iv : Z * Z => 0xb8000 <= fst iv) X ->
  xclient_range LB SP X A n.
Proof.
  intros LB SP X A n H1 H2 H3 H4 H5 H6 H7 FX. split.
  - right. left. repeat split; assumption.
  - eapply Forall_impl; [| exact FX]. intros [lo hi] K. cbn in *. lia.
Qed.
