(* [comment removed for export] *)
Lemma rw_cells_xpres_hi : forall LB SP X m m' A cs,
  xpres LB SP X m m' -> rw_cells usegs m A cs -> SP <= A ->
  Forall (fun iv : Z * Z => A + Z.of_nat (cells_size cs) <= fst iv \/ snd iv <= A) X ->
  rw_cells usegs m' A cs.
Proof.
  intros LB SP X m m' A cs PRES RC HA FX. eapply xpres_rw_cells; [exact PRES | exact RC |]. split; [left; exact HA | exact FX].
Qed.

(* [comment removed for export] *)
Lemma bytes_at_xpres : forall LB SP X m m' A bs,
  xpres LB SP X m m' -> bytes_at usegs m A bs -> rclient_range LB SP A (Z.of_nat (length bs)) ->
  Forall (fun iv : Z * Z => A + Z.of_nat (length bs) <= fst iv \/ snd iv <= A) X ->
  bytes_at usegs m' A bs.
Proof.
  intros LB SP X m m' A bs PRES BA RR FX. eapply xpres_bytes_at; [exact PRES | exact BA |]. split; [exact RR | exact FX].
Qed.

(* [comment removed for export] *)
Lemma stk_xpres : forall LB SP X m m' lo hi,
  xpres LB SP X m m' -> stk usegs m lo hi -> SP <= lo -> Forall (fun iv : Z * Z => hi <= fst iv \/ snd iv <= lo) X ->
  stk usegs m' lo hi.
Proof. intros. eapply xpres_stk; eauto. Qed.

(* [comment removed for export] *)
Lemma rclient_range_weaken : forall LB LB' SP SP' A n,
  rclient_range LB SP A n -> SP' <= SP -> (forall b, In b LB -> In b LB') -> rclient_range LB' SP' A n.
Proof.
  intros LB LB' SP SP' A n [H|[H|(b & Hb & R1 & R2)]] HS HL; [left; lia | right; left; exact H | right; right].
  exists b. split; [apply HL; exact Hb|]. split; assumption.
Qed.

